def consolidate_legacy_activity(apps, schema_editor):
    AuditEvent = apps.get_model("observability", "AuditEvent")
    RequestAudit = apps.get_model("core", "AuditLog")
    StructuredAudit = apps.get_model("monitoring", "AuditLog")
    db = schema_editor.connection.alias

    # The core ledger contains every authenticated request and is the authoritative
    # source for request counts. Bodies are intentionally not migrated.
    for row in RequestAudit.objects.using(db).all().iterator(chunk_size=1000):
        method = (row.method or "").upper()[:10]
        action = f"{method.lower()}_{'failed' if row.status_code >= 400 else 'completed'}"
        AuditEvent.objects.using(db).create(
            actor_id=row.user_id, action=action, resource_type="request",
            resource_id=row.path[:120], outcome="failed" if row.status_code >= 400 else "success",
            ip_address=row.ip_address or None, request_path=row.path[:500],
            http_method=method, http_status=row.status_code, module="request",
            resource=row.path[:220], created_at=row.created_at,
            metadata={"source": "migrated_request_ledger", "user_agent": (row.user_agent or "")[:255]},
        )

    # The structured log also held request outcomes. Those are duplicates of the
    # core ledger above; preserve only business/security events from that table.
    request_actions = {f"{method}_{outcome}" for method in ("get", "head", "options", "post", "put", "patch", "delete") for outcome in ("completed", "failed")}
    for row in StructuredAudit.objects.using(db).all().iterator(chunk_size=1000):
        if row.action in request_actions and "request_id=" in (row.resource or ""):
            continue
        AuditEvent.objects.using(db).create(
            actor_id=row.user_id, action=row.action, resource_type=row.module or "application",
            resource_id=row.resource or "", outcome="recorded", ip_address=row.ip_address,
            module=row.module or "", resource=row.resource or "",
            old_value=row.old_value, new_value=row.new_value,
            previous_hash=row.previous_hash, hash=row.hash or "", created_at=row.timestamp,
            metadata={"source": "migrated_structured_activity"},
        )


